96	     * 登记限速令（版本 1，状态 ACTIVE）。区段未登记、时段非法、速度越界均返回 422。
97	     */
98	    public RestrictionResponse register(RestrictionRegisterRequest req) {
99	        validateWindow(req.startUtc(), req.endUtc());
100	        validateSpeed(req.maxSpeedKmh());
101	        String hash = sha256(OP_REGISTER + '\n' + req.restrictionKey() + '\n' + req.sectionId()
102	                + '\n' + req.startUtc().toEpochMilli() + '\n' + req.endUtc().toEpochMilli()
103	                + '\n' + req.maxSpeedKmh() + '\n' + operator(req.operator()));
104	        Optional<RestrictionResponse> replay = replayIfPresent(OP_REGISTER, req.requestKey(), hash);
