115	                    throw conflict("RESTRICTION_KEY_EXISTS", "restrictionKey 已存在: "
116	                            + req.restrictionKey());
117	                }
118	                long now = clock.millis();
119	                restrictionRepo.insertRestriction(req.restrictionKey(), req.sectionId(),
120	                        req.startUtc(), req.endUtc(), req.maxSpeedKmh(), req.operator(), now);
121	                RestrictionResponse response = toResponse(
122	                        restrictionRepo.findByKey(req.restrictionKey()).orElseThrow());
123	                idemRepo.insert(OP_REGISTER, req.requestKey(), hash, toJson(response), now);
124	                return response;
125	            });
126	        } catch (DuplicateKeyException e) {
127	            return replayIfPresent(OP_REGISTER, req.requestKey(), hash)
128	                    .orElseThrow(() -> conflict("RESTRICTION_KEY_EXISTS",
129	                            "restrictionKey 已存在: " + req.restrictionKey()));
130	        }
131	    }
132	
133	    /**
134	     * 撤销限速令：状态置为 REVOKED，不再影响后续发布或改签；已生成的重排记录不改写。
135	     */
136	    public RestrictionResponse revoke(String restrictionKey, RestrictionActionRequest req) {
137	        String hash = sha256(OP_REVOKE + '\n' + restrictionKey + '\n' + operator(req.operator()));
138	        Optional<RestrictionResponse> replay = replayIfPresent(OP_REVOKE, req.requestKey(), hash);
139	        if (replay.isPresent()) {
140	            return replay.get();
141	        }
142	        try {
143	            return tx.execute(status -> {
144	                SpeedRestriction restriction = restrictionRepo.findByKeyForUpdate(restrictionKey)
145	                        .orElseThrow(() -> notFound("RESTRICTION_NOT_FOUND",
146	                                "限速令不存在: " + restrictionKey));
147	                if (restriction.status() == RestrictionStatus.REVOKED) {
148	                    throw conflict("RESTRICTION_STATE_CONFLICT",
149	                            "限速令已撤销: " + restrictionKey);
150	                }
151	                long now = clock.millis();
152	                restrictionRepo.revokeRestriction(restriction.id(), now);
153	                RestrictionResponse response = toResponse(
154	                        restrictionRepo.findByKey(restrictionKey).orElseThrow());
155	                idemRepo.insert(OP_REVOKE, req.requestKey(), hash, toJson(response), now);
156	                return response;
157	            });
158	        } catch (DuplicateKeyException e) {
159	            return replayIfPresent(OP_REVOKE, req.requestKey(), hash)
160	                    .orElseThrow(() -> conflict("RESTRICTION_STATE_CONFLICT",
161	                            "限速令已撤销: " + restrictionKey));
162	        }
163	    }
164	
165	    /**
166	     * 修订限速令：调整时段与最高速度，版本加一；已撤销不可修订；重排记录保持修订前快照。
167	     */
168	    public RestrictionResponse revise(String restrictionKey, RestrictionReviseRequest req) {
169	        validateWindow(req.startUtc(), req.endUtc());
170	        validateSpeed(req.maxSpeedKmh());
171	        String hash = sha256(OP_REVISE + '\n' + restrictionKey + '\n'
172	                + req.startUtc().toEpochMilli() + '\n' + req.endUtc().toEpochMilli()
173	                + '\n' + req.maxSpeedKmh() + '\n' + operator(req.operator()));
174	        Optional<RestrictionResponse> replay = replayIfPresent(OP_REVISE, req.requestKey(), hash);
175	        if (replay.isPresent()) {
176	            return replay.get();
177	        }
178	        try {
179	            return tx.execute(status -> {
180	                SpeedRestriction restriction = restrictionRepo.findByKeyForUpdate(restrictionKey)
181	                        .orElseThrow(() -> notFound("RESTRICTION_NOT_FOUND",
182	                                "限速令不存在: " + restrictionKey));
183	                if (restriction.status() == RestrictionStatus.REVOKED) {
184	                    throw conflict("RESTRICTION_STATE_CONFLICT",
185	                            "限速令已撤销，不可修订: " + restrictionKey);
186	                }
187	                long now = clock.millis();
188	                restrictionRepo.reviseRestriction(restriction.id(), req.startUtc(), req.endUtc(),
189	                        req.maxSpeedKmh(), restriction.version() + 1, req.operator(), now);
190	                RestrictionResponse response = toResponse(
191	                        restrictionRepo.findByKey(restrictionKey).orElseThrow());
192	                idemRepo.insert(OP_REVISE, req.requestKey(), hash, toJson(response), now);
193	                return response;
194	            });
195	        } catch (DuplicateKeyException e) {
196	            return replayIfPresent(OP_REVISE, req.requestKey(), hash)
197	                    .orElseThrow(() -> conflict("RESTRICTION_STATE_CONFLICT",
198	                            "限速令状态冲突: " + restrictionKey));
199	        }
200	    }
