202	    /**
203	     * 查询限速令明细，不存在返回 404。
204	     */
205	    public RestrictionResponse getRestriction(String restrictionKey) {
206	        return toResponse(restrictionRepo.findByKey(restrictionKey)
207	                .orElseThrow(() -> notFound("RESTRICTION_NOT_FOUND", "限速令不存在: " + restrictionKey)));
208	    }
