210	    /**
211	     * 查询限速令历史列表；sectionId 为空时返回全部，按业务键排序。读取不改变状态。
212	     */
213	    public List<RestrictionResponse> listRestrictions(String sectionId) {
214	        List<SpeedRestriction> restrictions = sectionId == null || sectionId.isBlank()
215	                ? restrictionRepo.findAll() : restrictionRepo.findBySection(sectionId);
216	        return restrictions.stream().map(this::toResponse).toList();
217	    }
