219	    /**
220	     * 诊断：区段在某 UTC 时刻的生效限速（多条叠加以最低速度为准）。
221	     * effectiveSpeedKmh 为 null 表示该时刻无生效限速。区段未登记返回 404。
222	     */
223	    public EffectiveLimitView effectiveLimit(String sectionId, Instant at) {
224	        if (restrictionRepo.findSection(sectionId).isEmpty()) {
225	            throw notFound("SECTION_NOT_FOUND", "区段档案不存在: " + sectionId);
226	        }
227	        List<SpeedRestriction> active = restrictionRepo.findActiveAt(sectionId, at);
228	        Integer effective = active.stream().map(SpeedRestriction::maxSpeedKmh)
229	                .min(Integer::compareTo).orElse(null);
230	        return new EffectiveLimitView(sectionId, at, effective,
231	                active.stream().map(this::toResponse).toList());
232	    }
233	
234	    // ---------- 内部实现 ----------
235	
236	    private RestrictionResponse toResponse(SpeedRestriction r) {
237	        return new RestrictionResponse(r.restrictionKey(), r.sectionId(), r.startUtc(), r.endUtc(),
238	                r.maxSpeedKmh(), r.version(), r.status().name(), r.operator());
239	    }
240	
241	    /**
242	     * 时段校验：end 必须晚于 start（UTC 左闭右开），违反返回 422 并携带实际值。
243	     */
244	    private void validateWindow(Instant startUtc, Instant endUtc) {
245	        if (!endUtc.isAfter(startUtc)) {
246	            Map<String, Object> detail = new LinkedHashMap<>();
247	            detail.put("type", "INVALID_TIME_WINDOW");
248	            detail.put("actualStartUtc", startUtc.toString());
249	            detail.put("actualEndUtc", endUtc.toString());
250	            detail.put("required", "endUtc 必须晚于 startUtc（左闭右开）");
251	            throw unprocessable("INVALID_TIME_WINDOW", "限速时段非法: endUtc 必须晚于 startUtc", detail);
252	        }
253	    }
254	
255	    /**
256	     * 速度校验：最高速度必须在 10～300 km/h，违反返回 422 并携带实际值与要求范围。
257	     */
258	    private void validateSpeed(int maxSpeedKmh) {
259	        if (maxSpeedKmh < MIN_SPEED_KMH || maxSpeedKmh > MAX_SPEED_KMH) {
260	            Map<String, Object> detail = new LinkedHashMap<>();
261	            detail.put("type", "INVALID_SPEED");
262	            detail.put("actualSpeedKmh", maxSpeedKmh);
263	            detail.put("requiredMinSpeedKmh", MIN_SPEED_KMH);
264	            detail.put("requiredMaxSpeedKmh", MAX_SPEED_KMH);
265	            throw unprocessable("INVALID_SPEED",
266	                    "限速速度非法: " + maxSpeedKmh + " km/h，合法范围 10～300", detail);
267	        }
268	    }
269	
270	    private Map<String, Object> detail(String key, Object value) {
271	        Map<String, Object> detail = new LinkedHashMap<>();
272	        detail.put("type", "INVALID_SECTION");
273	        detail.put(key, value);
274	        return detail;
275	    }
276	
277	    private String operator(String operator) {
278	        return operator == null ? "" : operator;
279	    }
280	
281	    /**
282	     * 幂等重放：存在记录且参数一致返回首次结果；参数不一致抛 409。
283	     */
284	    private Optional<RestrictionResponse> replayIfPresent(String opType, String requestKey,
285	                                                          String hash) {
286	        return idemRepo.find(opType, requestKey).map(record -> {
287	            if (!record.requestHash().equals(hash)) {
288	                throw conflict("IDEMPOTENT_KEY_REUSED", "requestKey 已用于其他参数: " + requestKey);
289	            }
290	            return fromJson(record.responseJson());
291	        });
292	    }
293	
294	    private String sha256(String text) {
295	        try {
296	            MessageDigest digest = MessageDigest.getInstance("SHA-256");
297	            byte[] hashed = digest.digest(text.getBytes(StandardCharsets.UTF_8));
298	            StringBuilder hex = new StringBuilder(hashed.length * 2);
299	            for (byte b : hashed) {
300	                hex.append(Character.forDigit((b >> 4) & 0xF, 16));
301	                hex.append(Character.forDigit(b & 0xF, 16));
302	            }
303	            return hex.toString();
304	        } catch (NoSuchAlgorithmException e) {
305	            throw new IllegalStateException(e);
306	        }
307	    }
308	
309	    private String toJson(Object response) {
310	        try {
311	            return objectMapper.writeValueAsString(response);
312	        } catch (Exception e) {
313	            throw new IllegalStateException("响应序列化失败", e);
314	        }
315	    }
316	
317	    private RestrictionResponse fromJson(String json) {
318	        try {
319	            return objectMapper.readValue(json, RestrictionResponse.class);
320	        } catch (Exception e) {
321	            throw new IllegalStateException("幂等响应反序列化失败", e);
322	        }
323	    }
324	
325	    private ApiException unprocessable(String code, String message, Map<String, Object> detail) {
326	        return new ApiException(HttpStatus.UNPROCESSABLE_ENTITY, code, message, List.of(detail));
327	    }
328	
329	    private ApiException notFound(String code, String message) {
330	        return new ApiException(HttpStatus.NOT_FOUND, code, message);
331	    }
332	
333	    private ApiException conflict(String code, String message) {
334	        return new ApiException(HttpStatus.CONFLICT, code, message);
335	    }
336	}
