                + "\",\"sectionId\":\"" + sectionId + "\",\"startUtc\":\"" + startIso
                + "\",\"endUtc\":\"" + endIso + "\",\"maxSpeedKmh\":" + maxSpeed
                + (operator == null ? "" : ",\"operator\":\"" + operator + "\"") + "}";
    }
}

